//! The offline material one party holds when the online phase starts, whichever way it was produced: dealt by a TRUSTED DEALER over
//! the mesh ([`super::protocol::run_dealer`]) or generated by the parties themselves from oblivious transfer with NO dealer
//! ([`super::offline`]).
use crate::mpc_net::{Aw, Pa, SlotDisclosure};

/// Which offline phase runs.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Offline {
    /// A separate process that knows every share and key deals the material (needs an explicit opt-in).
    TrustedDealer,
    /// The parties derive everything themselves from OT (the default).
    NoDealer,
}

impl Offline {
    pub fn as_str(&self) -> &'static str {
        match self {
            Offline::TrustedDealer => "trusted-dealer",
            Offline::NoDealer => "no-dealer",
        }
    }

    pub fn parse(s: &str) -> Option<Offline> {
        match s {
            "trusted-dealer" => Some(Offline::TrustedDealer),
            "no-dealer" => Some(Offline::NoDealer),
            _ => None,
        }
    }
}

/// The OT transcript of the triple products, for attributing a failed sacrifice (no-dealer mode).
pub struct Forensics {
    pub gadget: Vec<u64>,
    /// Choice bits per product item (the encoded width).
    pub rows: usize,
    /// Product slots per triple: the product and one per sacrifice partner.
    pub slots: usize,
    /// My disclosure for triple `t` (the triple is discarded when this is used).
    pub disclose: Box<dyn Fn(usize) -> Vec<SlotDisclosure>>,
}

pub struct Prep {
    pub mode: Offline,
    /// Whether the shares carry pairwise tags (identifiable abort).
    pub tagged: bool,
    /// My pairwise verification key.
    pub delta: u64,
    /// My share of each global MAC key, pairwise-authenticated.
    pub alpha: Vec<Pa>,
    /// Triples with their sacrifice partners: `triples[t] = [a, b, c, a-hat_1, c-hat_1, ...]` (the partners share b).
    pub triples: Vec<Vec<Aw>>,
    /// trusted-dealer: the authenticated random MASKS r of each (owner, chain), `inputs[owner * C + c]`; no-dealer: the authenticated
    /// input bits themselves, same indexing.
    pub inputs: Vec<Aw>,
    /// My own plaintext side of `inputs`: the masks r (trusted-dealer) or my input bits (no-dealer), one per chain.
    pub my_plain: Vec<u64>,
    /// no-dealer only: an authenticated random mask for the input-consistency check.
    pub check_mask: Option<Aw>,
    pub forensics: Option<Forensics>,
}
